import { randomUUID } from "node:crypto";
import type { DatabaseSync } from "node:sqlite";

import { hashJson } from "../canonical-hash.js";
import { compilationInputsHash, compiledIdentity } from "./compiled.js";
import { compileLeaves, type CompileLeaf, type Compiled } from "./compile.js";
import { coreCheckErrors } from "./core-checks.js";
import { bumpWorkbenchRevision, withTransaction } from "./db.js";
import { checkEntry, entryWithMechanics, resolveCheckedEntity, semanticAuthoringDataRoot } from "./entries.js";
import { cruncherGateErrors } from "./gates.js";
import { assertReviewer, requireHuman, type Actor } from "./authority.js";
import { tiledSources } from "./leaf-view.js";
import { ownAbilityIds } from "./own-abilities.js";
import { approvedCompanions, compiledPublicationErrors, openPublicationChecker, type FactionRecord } from "./publication-projection.js";
import type { ProjectionChecker } from "../mfm/apply.js";

/**
 * Shapes: sources fully described by leaves, grouped by the order of their leaf roles and
 * families. Every member of a shape compiles by the same rules, so a reviewer checks a few
 * renders and approves the shape for all of them at once.
 */

class ShapeError extends Error {
  readonly status: number;

  constructor(status: 404 | 409 | 422, message: string) {
    super(message);
    this.name = "ShapeError";
    this.status = status;
  }
}

type Member = { id: number; faction_id: string; ability_id: string; name: string | null; source_hash: string; source_text: string; source_type: string | null; leaves: CompileLeaf[] };

/** Current sources fully described by trusted leaves, optionally for one faction. */
function tiledMembers(db: DatabaseSync, factionId: string | null): Member[] {
  return tiledSources(db, { factionId });
}

/**
 * Each member's compiler context: its own ability and owning-faction unit and weapon catalogs, as
 * the compile gates pass them (gates.ts), so a named weapon resolves here too.
 */
function ownOptions(db: DatabaseSync): (member: Member) => { abilityId?: string; name?: string; units: { faction_id: string }; weapons: { faction_id: string; source_type: string } } {
  const own = ownAbilityIds(db, semanticAuthoringDataRoot());
  return (member) => ({
    abilityId: own.get(member.id),
    name: member.name ?? undefined,
    units: { faction_id: member.faction_id },
    weapons: { faction_id: member.faction_id, source_type: member.source_type ?? "" },
  });
}

type EntryState = { status: string; inputs_hash: string; mechanics_hash: string };

function entryStates(db: DatabaseSync): Map<number, EntryState[]> {
  const states = new Map<number, EntryState[]>();
  for (const row of db.prepare("SELECT ability_version_id, status, inputs_hash, mechanics_json, core_json FROM compiled_entries WHERE status IN ('approved', 'rejected')").all() as Array<{ ability_version_id: number; status: string; inputs_hash: string; mechanics_json: string; core_json: string | null }>) {
    const list = states.get(row.ability_version_id) ?? [];
    list.push({ status: row.status, inputs_hash: row.inputs_hash, mechanics_hash: hashJson(compiledIdentity(JSON.parse(row.mechanics_json), row.core_json ? JSON.parse(row.core_json) : null)) });
    states.set(row.ability_version_id, list);
  }
  return states;
}

/** approved: this exact compilation is approved; stale: an approval exists for older leaves; rejected: a reviewer refused this compilation. */
function memberState(states: EntryState[] | undefined, inputsHash: string, compiled: Compiled): "approved" | "rejected" | "stale" | "open" {
  const mechanicsHash = compiled.ok ? hashJson(compiledIdentity(compiled.mechanics, compiled.core ?? null)) : null;
  const current = (states ?? []).filter((state) => state.inputs_hash === inputsHash && state.mechanics_hash === mechanicsHash);
  if (current.some((state) => state.status === "approved")) return "approved";
  if (current.some((state) => state.status === "rejected")) return "rejected";
  return (states ?? []).some((state) => state.status === "approved") ? "stale" : "open";
}

export type ShapeSummary = { signature: string; members: number; distinct_sources: number; compiles: number; approved: number; open: number; first_error: string | null };

export function listShapes(db: DatabaseSync, options: { factionId?: string } = {}): { shapes: ShapeSummary[]; tiled: number } {
  const members = tiledMembers(db, options.factionId?.trim() || null);
  const states = entryStates(db);
  const compileOptions = ownOptions(db);
  const shapes = new Map<string, ShapeSummary & { sources: Set<string> }>();
  for (const member of members) {
    const compiled = compileLeaves(member.leaves, member.source_text, compileOptions(member));
    const entry = shapes.get(compiled.signature) ?? { signature: compiled.signature, members: 0, distinct_sources: 0, compiles: 0, approved: 0, open: 0, first_error: null, sources: new Set<string>() };
    entry.members += 1;
    entry.sources.add(member.source_hash);
    if (compiled.ok) entry.compiles += 1;
    else entry.first_error ??= compiled.errors[0] ?? null;
    const state = memberState(states.get(member.id), compilationInputsHash(db, member.id), compiled);
    if (state === "approved") entry.approved += 1;
    if (compiled.ok && (state === "open" || state === "stale")) entry.open += 1;
    shapes.set(compiled.signature, entry);
  }
  return {
    tiled: members.length,
    shapes: [...shapes.values()].map(({ sources, ...shape }) => ({ ...shape, distinct_sources: sources.size }))
      .sort((left, right) => right.open - left.open || right.members - left.members || left.signature.localeCompare(right.signature)),
  };
}

export type ShapeMember = {
  ability_version_ids: number[];
  abilities: Array<{ ability_version_id: number; faction_id: string; ability_id: string; name: string | null }>;
  source_text: string;
  authored_text: string | null;
  compiled_text: string | null;
  /** The stratagem target the leaves set on the core record, when they set one. */
  core_target: Record<string, unknown> | Array<Record<string, unknown>> | null;
  differs: boolean;
  state: "approved" | "rejected" | "stale" | "open";
  errors: string[];
};

function render(factionId: string, abilityId: string, compiled: Compiled): { authored: string | null; compiled: string | null; errors: string[]; differs: boolean } {
  let original: Record<string, unknown>;
  try {
    original = resolveCheckedEntity(semanticAuthoringDataRoot(), factionId, abilityId).entry;
  } catch (error) {
    return { authored: null, compiled: null, errors: [error instanceof Error ? error.message : String(error)], differs: true };
  }
  const authored = checkEntry(original).rendered_text;
  if (!compiled.ok) return { authored, compiled: null, errors: compiled.errors, differs: true };
  const entry = entryWithMechanics(original, compiled.mechanics);
  const check = checkEntry(entry);
  if (!check.rendered_text && check.errors.length === 0) check.errors.push("The describer produced no text.");
  check.errors.push(...coreCheckErrors(semanticAuthoringDataRoot(), abilityId, compiled.checks));
  check.errors.push(...cruncherGateErrors(semanticAuthoringDataRoot(), factionId, abilityId, entry));
  const fields = ["effect", "scope", "behavior", "optional", "trigger", "usage"] as const;
  const differs = fields.some((field) => hashJson(original[field] ?? null) !== hashJson(entry[field] ?? null));
  return { authored, compiled: check.rendered_text, errors: check.errors, differs };
}

/**
 * One shape's members, byte-identical sources folded together, with the authored render beside
 * the compiled one. Members whose compiled entry differs from what is authored come first.
 */
export function getShape(db: DatabaseSync, signature: string, options: { factionId?: string } = {}): { signature: string; members: ShapeMember[] } {
  const states = entryStates(db);
  const groups = new Map<string, ShapeMember>();
  const compileOptions = ownOptions(db);
  for (const member of tiledMembers(db, options.factionId?.trim() || null)) {
    const compiled = compileLeaves(member.leaves, member.source_text, compileOptions(member));
    if (compiled.signature !== signature) continue;
    const state = memberState(states.get(member.id), compilationInputsHash(db, member.id), compiled);
    const shown = render(member.faction_id, member.ability_id, compiled);
    const key = `${member.source_hash}\u0000${shown.compiled}\u0000${shown.authored}\u0000${state}\u0000${compiled.ok ? JSON.stringify(compiled.core ?? null) : ""}`;
    const group = groups.get(key) ?? {
      ability_version_ids: [], abilities: [], source_text: member.source_text, authored_text: shown.authored,
      compiled_text: shown.compiled, core_target: compiled.ok ? compiled.core?.target_restrictions ?? null : null, differs: shown.differs, state, errors: shown.errors,
    };
    group.ability_version_ids.push(member.id);
    group.abilities.push({ ability_version_id: member.id, faction_id: member.faction_id, ability_id: member.ability_id, name: member.name });
    groups.set(key, group);
  }
  if (groups.size === 0) throw new ShapeError(404, `No fully described source has the shape ${signature}.`);
  return {
    signature,
    members: [...groups.values()].sort((left, right) => Number(right.differs) - Number(left.differs) || right.ability_version_ids.length - left.ability_version_ids.length),
  };
}

export type ReviewMember = {
  ability_version_id: number; faction_id: string; ability_id: string; name: string | null; signature: string;
  state: ShapeMember["state"]; differs: boolean; authored_text: string | null; compiled_text: string | null; errors: string[];
};

/**
 * Every fully described source, each compiled once, with its shape and both renders: the
 * per-faction review sheet's rows. `abilityVersionIds` narrows the set.
 */
export function reviewMembers(db: DatabaseSync, options: { factionId?: string; abilityVersionIds?: ReadonlySet<number> } = {}): ReviewMember[] {
  const states = entryStates(db);
  const compileOptions = ownOptions(db);
  const rows: ReviewMember[] = [];
  for (const member of tiledMembers(db, options.factionId?.trim() || null)) {
    if (options.abilityVersionIds && !options.abilityVersionIds.has(member.id)) continue;
    const compiled = compileLeaves(member.leaves, member.source_text, compileOptions(member));
    const shown = render(member.faction_id, member.ability_id, compiled);
    rows.push({
      ability_version_id: member.id, faction_id: member.faction_id, ability_id: member.ability_id, name: member.name, signature: compiled.signature,
      state: memberState(states.get(member.id), compilationInputsHash(db, member.id), compiled),
      differs: shown.differs, authored_text: shown.authored, compiled_text: shown.compiled, errors: shown.errors,
    });
  }
  return rows;
}

function parse(value: unknown): { reviewer: string; signature: string; ids: number[] } {
  if (value === null || typeof value !== "object" || Array.isArray(value)) throw new ShapeError(422, "Expected {reviewer, signature, ability_version_ids}.");
  const input = value as Record<string, unknown>;
  if (typeof input.reviewer !== "string" || !input.reviewer.trim()) throw new ShapeError(422, "reviewer is required.");
  if (typeof input.signature !== "string" || !input.signature.trim()) throw new ShapeError(422, "signature is required.");
  if (!Array.isArray(input.ability_version_ids) || input.ability_version_ids.length === 0 || !input.ability_version_ids.every((id) => Number.isSafeInteger(id))) {
    throw new ShapeError(422, "ability_version_ids must list at least one source version.");
  }
  return { reviewer: input.reviewer, signature: input.signature, ids: [...new Set(input.ability_version_ids as number[])] };
}

/**
 * `checked` (approval only) holds the compiled identity each member's publication integrity was
 * checked against; a member whose compilation changed since then is refused.
 */
function decide(db: DatabaseSync, value: unknown, status: "approved" | "rejected", actor: Actor, checked?: ReadonlyMap<number, string>): { batch_id: string; recorded: number } {
  requireHuman(actor, `${status === "approved" ? "approve" : "reject"} compiled shapes`);
  const input = parse(value);
  assertReviewer(actor, input.reviewer);
  return withTransaction(db, () => {
    const members = new Map(tiledMembers(db, null).map((member) => [member.id, member]));
    const compileOptions = ownOptions(db);
    const batchId = `batch_${randomUUID()}`;
    db.prepare("INSERT INTO annotation_batches (id, operation, reviewer, created_at, metadata_json) VALUES (?, 'review', ?, ?, ?)")
      .run(batchId, input.reviewer, new Date().toISOString(), JSON.stringify({ action: `shape-${status}`, signature: input.signature }));
    const member = db.prepare("INSERT INTO batch_members (batch_id, entity_kind, entity_id) VALUES (?, ?, ?)");
    let recorded = 0;
    for (const id of input.ids) {
      const source = members.get(id);
      if (!source) throw new ShapeError(409, `Source version ${id} is no longer current and fully described; reload the shape.`);
      const compiled = compileLeaves(source.leaves, source.source_text, compileOptions(source));
      if (compiled.signature !== input.signature) throw new ShapeError(409, `${source.faction_id}/${source.ability_id} no longer has this shape; reload it.`);
      if (!compiled.ok) throw new ShapeError(422, `${source.faction_id}/${source.ability_id} does not compile: ${compiled.errors.join("; ")}`);
      if (status === "approved") {
        const shown = render(source.faction_id, source.ability_id, compiled);
        if (shown.errors.length > 0) throw new ShapeError(422, `${source.faction_id}/${source.ability_id} cannot be approved: ${shown.errors.join("; ")}`);
        if (checked?.get(id) !== hashJson(compiledIdentity(compiled.mechanics, compiled.core ?? null))) {
          throw new ShapeError(409, `${source.faction_id}/${source.ability_id} changed while its publication integrity was checked; reload it.`);
        }
      }
      const inputsHash = compilationInputsHash(db, id);
      const entryId = `compiled_${hashJson({ ability_version_id: id, inputs_hash: inputsHash, mechanics: compiledIdentity(compiled.mechanics, compiled.core ?? null), status })}`;
      if (db.prepare("SELECT 1 FROM compiled_entries WHERE id = ? AND status = ?").get(entryId, status)) continue;
      // The latest decision is the only one standing: a rejection revokes the approval it follows,
      // so a publication prepared from that approval no longer finds an approved entry.
      for (const previous of db.prepare("SELECT id, status FROM compiled_entries WHERE ability_version_id = ? AND status IN ('approved', 'rejected') AND id != ?").all(id, entryId) as Array<{ id: string; status: string }>) {
        db.prepare("UPDATE compiled_entries SET status = 'retracted' WHERE id = ?").run(previous.id);
        member.run(batchId, REPLACED_KIND[previous.status]!, previous.id);
      }
      db.prepare(`
        INSERT INTO compiled_entries (id, ability_version_id, shape_signature, mechanics_json, core_json, inputs_hash, status, batch_id, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET status = excluded.status, batch_id = excluded.batch_id
      `).run(entryId, id, compiled.signature, JSON.stringify(compiled.mechanics), compiled.core ? JSON.stringify(compiled.core) : null, inputsHash, status, batchId, new Date().toISOString());
      member.run(batchId, `compiled-entry-${status}`, entryId);
      recorded += 1;
    }
    bumpWorkbenchRevision(db);
    return { batch_id: batchId, recorded };
  });
}

/**
 * Why publishing each listed member's compiled entry would be refused, alone or together with
 * the faction's other approved entries, by source version,
 * with the compiled identity it was checked against. A member that is missing, has another shape
 * or does not compile is left to `decide`, which refuses it with its own reason.
 */
async function publicationChecks(db: DatabaseSync, input: { signature: string; ids: number[] }, coApproved: readonly FactionRecord[]): Promise<Map<number, { identity: string; errors: string[]; label: string }>> {
  const members = new Map(tiledMembers(db, null).map((member) => [member.id, member]));
  const compileOptions = ownOptions(db);
  const checks = new Map<number, { identity: string; errors: string[]; label: string }>();
  let checker: ProjectionChecker | undefined;
  try {
    for (const id of input.ids) {
      const source = members.get(id);
      if (!source) continue;
      const compiled = compileLeaves(source.leaves, source.source_text, compileOptions(source));
      if (!compiled.ok || compiled.signature !== input.signature) continue;
      checker ??= openPublicationChecker();
      const errors = await compiledPublicationErrors(checker, source.faction_id, {
        ability_id: source.ability_id, mechanics: compiled.mechanics, core: compiled.core ?? null, source_text: source.source_text,
      }, [...approvedCompanions(db, source.faction_id), ...coApproved.filter((record) => record.faction_id === source.faction_id)]);
      checks.set(id, { identity: hashJson(compiledIdentity(compiled.mechanics, compiled.core ?? null)), errors, label: `${source.faction_id}/${source.ability_id}` });
    }
  } finally {
    checker?.close();
  }
  return checks;
}

/**
 * The current compiled records of these source versions, for approvals decided together: records
 * that depend on each other (a stance and the rules naming its options) pass integrity only as one
 * publication. A version that is not fully described or does not compile is left out.
 */
export function compiledRecordsOf(db: DatabaseSync, ids: Iterable<number>): FactionRecord[] {
  const wanted = new Set(ids);
  const compileOptions = ownOptions(db);
  const records: FactionRecord[] = [];
  for (const source of tiledMembers(db, null)) {
    if (!wanted.has(source.id)) continue;
    const compiled = compileLeaves(source.leaves, source.source_text, compileOptions(source));
    if (!compiled.ok) continue;
    records.push({ faction_id: source.faction_id, ability_id: source.ability_id, mechanics: compiled.mechanics, core: compiled.core ?? null, source_text: source.source_text });
  }
  return records;
}

/**
 * Approve the compiled entry of each listed member of one shape. A member publication would
 * refuse (the gates' integrity check, run before the approval transaction) is refused here;
 * `coApproved` are records approved in the same review, which publication may write alongside.
 */
export async function approveShape(db: DatabaseSync, value: unknown, actor: Actor, coApproved: readonly FactionRecord[] = []): Promise<{ batch_id: string; recorded: number }> {
  requireHuman(actor, "approve compiled shapes");
  const input = parse(value);
  assertReviewer(actor, input.reviewer);
  const checks = await publicationChecks(db, input, coApproved);
  for (const check of checks.values()) {
    if (check.errors.length > 0) throw new ShapeError(422, `${check.label} cannot be approved: integrity: ${check.errors.join("; ")}`);
  }
  return decide(db, value, "approved", actor, new Map([...checks].map(([id, check]) => [id, check.identity])));
}

/** Refuse the compiled entry of each listed member until its leaves change. */
export function rejectShapeMembers(db: DatabaseSync, value: unknown, actor: Actor): { batch_id: string; recorded: number } {
  return decide(db, value, "rejected", actor);
}

type ApprovedEntry = { id: string; inputs_hash: string; mechanics_json: string; core_json: string | null };

/** Each listed source's approved entry recorded under its current inputs, if it has one. */
export function approvalsOnCurrentInputs(db: DatabaseSync, abilityVersionIds: Iterable<number>): Map<number, ApprovedEntry> {
  const approvedOf = db.prepare("SELECT id, inputs_hash, mechanics_json, core_json FROM compiled_entries WHERE ability_version_id = ? AND status = 'approved'");
  const out = new Map<number, ApprovedEntry>();
  for (const id of new Set(abilityVersionIds)) {
    const inputsHash = compilationInputsHash(db, id);
    const entry = (approvedOf.all(id) as ApprovedEntry[]).find((row) => row.inputs_hash === inputsHash);
    if (entry) out.set(id, entry);
  }
  return out;
}

/**
 * Carry approvals across a family-version bump. `before` holds each touched source's approval on
 * its inputs before the bump moved its leaves; a source whose compilation is still byte-identical
 * to that entry (mechanics and core) has the entry re-recorded under its new inputs, in `batchId`.
 * The record gates are not rerun here: the approved mechanics are unchanged, and publication
 * re-runs every gate. Any other change leaves the source stale for review.
 */
export function carryApprovals(db: DatabaseSync, before: ReadonlyMap<number, ApprovedEntry>, batchId: string): number {
  if (before.size === 0) return 0;
  const compileOptions = ownOptions(db);
  const insert = db.prepare(`
    INSERT INTO compiled_entries (id, ability_version_id, shape_signature, mechanics_json, core_json, inputs_hash, status, batch_id, created_at)
    VALUES (?, ?, ?, ?, ?, ?, 'approved', ?, ?)
    ON CONFLICT(id) DO UPDATE SET status = excluded.status, batch_id = excluded.batch_id
  `);
  const member = db.prepare("INSERT OR IGNORE INTO batch_members (batch_id, entity_kind, entity_id) VALUES (?, ?, ?)");
  let carried = 0;
  for (const source of tiledSources(db, { abilityVersionIds: new Set(before.keys()) })) {
    const prior = before.get(source.id);
    if (!prior) continue;
    const inputsHash = compilationInputsHash(db, source.id);
    if (inputsHash === prior.inputs_hash) continue;
    const compiled = compileLeaves(source.leaves, source.source_text, compileOptions(source));
    if (!compiled.ok) continue;
    const identity = compiledIdentity(compiled.mechanics, compiled.core ?? null);
    if (hashJson(identity) !== hashJson(compiledIdentity(JSON.parse(prior.mechanics_json), prior.core_json ? JSON.parse(prior.core_json) : null))) continue;
    const entryId = `compiled_${hashJson({ ability_version_id: source.id, inputs_hash: inputsHash, mechanics: identity, status: "approved" })}`;
    db.prepare("DELETE FROM compiled_entries WHERE id = ?").run(prior.id);
    insert.run(entryId, source.id, compiled.signature, JSON.stringify(compiled.mechanics), compiled.core ? JSON.stringify(compiled.core) : null, inputsHash, batchId, new Date().toISOString());
    member.run(batchId, "compiled-entry-carried", entryId);
    carried += 1;
  }
  return carried;
}

/** The batch member recording a decision replaced by a later one, by the replaced entry's status. */
const REPLACED_KIND: Record<string, string> = { approved: "compiled-entry-replaced", rejected: "compiled-entry-replaced-rejected" };
const RESTORED_STATUS: Record<string, string> = { "compiled-entry-replaced": "approved", "compiled-entry-replaced-rejected": "rejected" };

/** Text-keyed batch members this module owns. */
export const COMPILED_MEMBER_KINDS = new Set(["compiled-entry-approved", "compiled-entry-rejected", ...Object.keys(RESTORED_STATUS)]);

export function assertShapeUndo(db: DatabaseSync, members: ReadonlyArray<{ entity_kind: string; entity_id: string }>): void {
  for (const item of members) {
    if (item.entity_kind !== "compiled-entry-approved" && item.entity_kind !== "compiled-entry-rejected") continue;
    const row = db.prepare("SELECT status FROM compiled_entries WHERE id = ?").get(item.entity_id) as { status: string } | undefined;
    if (!row || row.status !== item.entity_kind.slice("compiled-entry-".length)) throw new ShapeError(409, "This batch cannot be undone because one of its compiled entries was later changed.");
  }
  for (const item of members) {
    if (RESTORED_STATUS[item.entity_kind] === undefined) continue;
    const row = db.prepare("SELECT status FROM compiled_entries WHERE id = ?").get(item.entity_id) as { status: string } | undefined;
    if (!row || row.status !== "retracted") throw new ShapeError(409, "This batch cannot restore a compiled entry it replaced because that entry was later changed.");
  }
}

export function applyShapeUndo(db: DatabaseSync, reversalId: string, members: ReadonlyArray<{ entity_kind: string; entity_id: string }>): void {
  const add = db.prepare("INSERT OR IGNORE INTO batch_members (batch_id, entity_kind, entity_id) VALUES (?, ?, ?)");
  for (const item of members) {
    if (item.entity_kind === "compiled-entry-approved" || item.entity_kind === "compiled-entry-rejected") {
      db.prepare("UPDATE compiled_entries SET status = 'retracted' WHERE id = ?").run(item.entity_id);
      add.run(reversalId, "compiled-entry-retracted", item.entity_id);
    }
  }
  for (const item of members) {
    const restored = RESTORED_STATUS[item.entity_kind];
    if (restored === undefined) continue;
    db.prepare("UPDATE compiled_entries SET status = ? WHERE id = ? AND status = 'retracted'").run(restored, item.entity_id);
    add.run(reversalId, "compiled-entry-restored", item.entity_id);
  }
}
